// Widgets at scale: spec parts (includes) generated by a project, widgets placed in a section of another page, the
// machine and runs archetypes, calculator bands.
import { test } from "node:test";
import assert from "node:assert/strict";
import { cpSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildWidgets, renderWidget, chromeFor } from "../src/index.js";
import { tempDir } from "../../core/test/support/temp.mjs";

const FIX = fileURLToPath(new URL("./fixture/", import.meta.url));
const T = (en) => ({ en, fa: en });
const widget = (archetype, path) => ({ archetype, usage: { surfaces: [{ path, placement: "section", how: T("In the page") }] }, application: { surface: T("Desk") }, architecture: { components: [T("Desk")], flow: T("a to b"), diagram: "docs/diagrams/lending.mmd" }, utility: { learns: T("How"), does: T("Run") } });
const part = {
  scenarios: [
    { id: "book-life", useCase: "lending", audiences: ["staff"], title: T("A book's life"), actors: [{ id: "desk", label: T("Desk"), kind: "organisation" }], steps: [{ id: "s1", actor: "desk", action: T("Shelved") }],
      machines: [
        { id: "loan", group: T("Loans"), title: T("Loan"), meta: [T("Rule 1")], states: [{ id: "out", label: T("Out"), kind: "initial" }, { id: "late", label: T("Late"), rules: [T("Send a reminder")] }, { id: "back", label: T("Back"), kind: "terminal" }], transitions: [{ from: "out", to: "back" }, { from: "out", to: "late" }, { from: "late", to: "back", label: T("returned") }] },
        { id: "hold", group: T("Holds"), title: T("Hold"), states: [{ id: "asked", label: T("Asked"), kind: "initial" }, { id: "ready", label: T("Ready") }], transitions: [{ from: "asked", to: "ready" }] },
      ],
      widgets: [widget("machine", "/books/")] },
    { id: "loan-check", useCase: "lending", audiences: ["staff"], title: T("Can this loan go out?"), actors: [{ id: "desk", label: T("Desk"), kind: "organisation" }],
      steps: [{ id: "card", actor: "desk", action: T("Card valid") }, { id: "limit", actor: "desk", action: T("Under the limit") }, { id: "stamp", actor: "desk", action: T("Stamped") }],
      cases: [{ id: "ok", label: T("Normal loan"), decision: "allow", inputs: [{ label: T("Books"), value: 2 }] }, { id: "over", label: T("Sixth book"), decision: "deny", stops: "limit", reason: T("limit_reached") }],
      inputs: [{ id: "n", label: T("Books"), type: "number", default: 3 }], outcomes: [{ id: "load", label: T("Load"), expr: "n * 20", bands: [{ min: 0, label: T("Light") }, { min: 50, label: T("Heavy"), text: T("Ask for help") }] }],
      widgets: [widget("runs", "/desk/"), widget("calculator", "/desk/")] },
  ],
};

test("a spec part joins the spec; machine, runs and calculator bands render and derive; a section placement keeps a widget off the widgets page", async (t) => {
  const dir = tempDir(t, "kw-scale-");
  cpSync(FIX, dir, { recursive: true });
  const spec = JSON.parse(readFileSync(join(dir, "widgets.spec.json"), "utf8"));
  spec.includes = ["part.json"]; spec.archetypes = [...spec.archetypes, "machine", "runs"];
  writeFileSync(join(dir, "widgets.spec.json"), JSON.stringify(spec));
  writeFileSync(join(dir, "part.json"), JSON.stringify(part));
  const { generated } = await buildWidgets(join(dir, "widgets.spec.json"));
  const en = (id) => generated.widgets.find((w) => w.id === id && w.locale === "en");
  const m = en("book-life-machine");
  assert.deepEqual(m.data.groups, ["Loans", "Holds"]);
  assert.deepEqual(m.data.machines[0].path, ["out", "back", "late"]);
  const r = en("loan-check-runs");
  assert.deepEqual(r.data.cases.map((k) => k.stop), [-1, 1]);
  assert.equal(en("loan-check-calculator").data.outputs[0].bands.length, 2);
  const loc = generated.locales.find((l) => l.code === "en"), c = chromeFor("en");
  const hm = renderWidget(m, { locale: loc, chrome: c }), hr = renderWidget(r, { locale: loc, chrome: c }), hc = renderWidget(en("loan-check-calculator"), { locale: loc, chrome: c });
  assert.match(hm, /data-kw-machine data-path="out back late"/);
  assert.match(hm, /role="tab"[^>]*>Loans <small>1<\/small>/);
  assert.match(hr, /data-kw-case="1" data-stop="1" data-decision="deny"/);
  assert.match(hr, /Stopped at Under the limit/);
  assert.match(hc, /<li data-min="50" data-on="1"><b>Heavy<\/b>/, "3 books × 20 = 60: the Heavy band");
});

test("a part that names a step that does not exist is refused", async (t) => {
  const dir = tempDir(t, "kw-scale-");
  cpSync(FIX, dir, { recursive: true });
  const spec = JSON.parse(readFileSync(join(dir, "widgets.spec.json"), "utf8"));
  spec.includes = ["part.json"]; spec.archetypes = [...spec.archetypes, "machine", "runs"];
  writeFileSync(join(dir, "widgets.spec.json"), JSON.stringify(spec));
  const bad = structuredClone(part); bad.scenarios[1].cases[1].stops = "nowhere";
  writeFileSync(join(dir, "part.json"), JSON.stringify(bad));
  await assert.rejects(buildWidgets(join(dir, "widgets.spec.json")), /stops at "nowhere"/);
});
